import {readFileSync,readdirSync,writeFileSync} from 'node:fs';

const ORIGIN='https://www.formadesignconsultants.com';
const year=new Date().getFullYear();
const nav=[['Services','services.html'],['ADUs','adu-design.html'],['Process','process.html'],['Locations','locations.html'],['About','team.html']];
const esc=s=>s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const schema=extra=>JSON.stringify({'@context':'https://schema.org','@graph':[{'@type':'Organization','@id':ORIGIN+'/#organization',name:'Forma Design Consultants',alternateName:['Forma','Forma Consulting Co.'],legalName:'Forma Consulting Co. LLC',url:ORIGIN+'/',logo:ORIGIN+'/logo1.jpg',telephone:'+1-209-449-6705',email:'cody@formadco.com',contactPoint:{'@type':'ContactPoint',telephone:'+1-209-449-6705',email:'cody@formadco.com',contactType:'customer service',areaServed:'US-CA',availableLanguage:['English','Spanish']},sameAs:['https://www.instagram.com/forma_consultants/'],areaServed:{'@type':'State',name:'California'},description:'Residential and light-commercial design, permit coordination, and consultant coordination in California.'},{'@type':'WebSite','@id':ORIGIN+'/#website',url:ORIGIN+'/',name:'Forma Design Consultants',alternateName:'Forma Consulting Co.',publisher:{'@id':ORIGIN+'/#organization'}},extra].filter(Boolean)}).replaceAll('<','\\u003c');
function header(active=''){
  return `<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="nav-wrap"><a class="brand" href="index.html" aria-label="Forma Design Consultants home"><span class="brand-mark">F</span>FORMA</a><button class="menu-button" type="button" aria-expanded="false" aria-controls="site-nav">Menu</button><nav class="site-nav" id="site-nav" aria-label="Primary">${nav.map(([label,url])=>`<a href="${url}"${active===url?' aria-current="page"':''}>${label}</a>`).join('')}<a class="nav-cta" href="consultant.html">Start a project</a></nav></div></header>`;
}
function footer(){return `<footer class="site-footer"><div class="footer-grid"><div><a class="footer-brand" href="index.html">FORMA</a><p>Clear plans. Coordinated permitting. A better path from property idea to buildable project.</p><p>Forma Design Consultants is the client-facing brand of Forma Consulting Co. LLC.</p></div><div class="footer-col"><h2>Services</h2><a href="adu-design.html">ADU design</a><a href="garage-conversion.html">Garage conversions</a><a href="additions-remodels.html">Additions & remodels</a><a href="commercial-plans.html">Commercial plans</a></div><div class="footer-col"><h2>Explore</h2><a href="process.html">Our process</a><a href="locations.html">Service areas</a><a href="floorplans.html">Concept plans</a><a href="team.html">About Forma</a></div><div class="footer-col"><h2>Connect</h2><a href="tel:+12094496705">(209) 449-6705</a><a href="mailto:cody@formadco.com">cody@formadco.com</a><a href="consultant.html">Project consultation</a><a href="https://www.instagram.com/forma_consultants/" rel="noopener" target="_blank">Instagram</a></div></div><div class="footer-meta"><span>© ${year} Forma Consulting Co. LLC. All rights reserved.</span><span><a href="privacy.html">Privacy</a> · <a href="terms.html">Terms</a></span></div></footer>`;}
function page({file,title,description,h1,kicker='California design + permitting',intro,body,active='',image='media/adu-hero.webp',schemaExtra}){
  const canonical=file==='index.html'?ORIGIN+'/':`${ORIGIN}/${file}`;
  const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="${canonical}"><meta name="robots" content="index,follow,max-image-preview:large"><meta property="og:type" content="website"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="${ORIGIN}/${image}"><meta name="twitter:card" content="summary_large_image"><meta name="theme-color" content="#0a0a0a"><link rel="icon" href="logo1.jpg"><link rel="stylesheet" href="style.css"><script type="application/ld+json">${schema(schemaExtra)}</script></head><body>${header(active)}<main id="main"><section class="page-hero"><div class="container"><div class="breadcrumbs"><a href="index.html">Home</a> / ${esc(h1)}</div><span class="eyebrow">${esc(kicker)}</span><h1>${h1}</h1><p>${intro}</p></div></section>${body}</main>${footer()}<script src="site.js" defer></script></body></html>`;
  writeFileSync(file,html);
}
const cards=items=>`<div class="grid-3">${items.map((x,i)=>`<article class="card reveal"><span class="number">0${i+1}</span><h3>${x[0]}</h3><p>${x[1]}</p>${x[2]?`<a class="card-link" href="${x[2]}">Learn more →</a>`:''}</article>`).join('')}</div>`;
const cta=(title='Make the first move.')=>`<section class="section"><div class="container cta-panel"><div><span class="eyebrow">Start with clarity</span><h2>${title}</h2><p>Tell us the property location, project type, and what you want the space to accomplish. We’ll review the basics and outline the right next step.</p></div><div><a class="button" href="consultant.html">Request a consultation</a></div></div></section>`;
const faq=items=>`<div class="faq">${items.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`;
const serviceSchema=(name,file,description)=>({'@type':'Service','@id':`${ORIGIN}/${file}#service`,name,description,provider:{'@id':ORIGIN+'/#organization'},areaServed:{'@type':'State',name:'California'}});

// Home
writeFileSync('index.html',`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ADU Design & Permit Plans in California | Forma</title><meta name="description" content="Forma Consulting Co. creates clear ADU, conversion, addition, remodel, and commercial plans with permitting coordination across California."><link rel="canonical" href="${ORIGIN}/"><meta name="robots" content="index,follow,max-image-preview:large"><meta property="og:type" content="website"><meta property="og:title" content="ADU Design & Permit Plans in California | Forma"><meta property="og:description" content="Design, permit plans, and consultant coordination for California property projects."><meta property="og:url" content="${ORIGIN}/"><meta property="og:image" content="${ORIGIN}/media/adu-hero.webp"><meta name="twitter:card" content="summary_large_image"><meta name="theme-color" content="#0a0a0a"><link rel="icon" href="logo1.jpg"><link rel="stylesheet" href="style.css"><script type="application/ld+json">${schema({'@type':'ProfessionalService','@id':ORIGIN+'/#service','name':'Forma Design Consultants','alternateName':'Forma Consulting Co.','url':ORIGIN+'/',telephone:'+1-209-449-6705',email:'cody@formadco.com',areaServed:{'@type':'State',name:'California'},parentOrganization:{'@id':ORIGIN+'/#organization'}})}</script></head><body>${header('index.html')}<main id="main"><section class="hero"><img class="hero-media" src="media/adu-hero.webp" width="1408" height="768" alt="Concept visualization of a modern California accessory dwelling unit"><div class="hero-content"><span class="eyebrow">California design + permit coordination</span><h1>Good projects start with clear plans.</h1><p>Forma turns ADU, conversion, addition, remodel, and commercial ideas into coordinated design documents—so owners and contractors can move forward with fewer unknowns.</p><div class="button-row"><a class="button light" href="consultant.html">Tell us about your project</a><a class="button" href="services.html">Explore services</a></div></div></section><div class="trust-strip"><div class="trust-grid"><span>Central Valley based</span><span>California service area</span><span>Permit coordination</span><span>Engineer + architect network</span></div></div><section class="section"><div class="container"><div class="section-head reveal"><div><span class="eyebrow">What we do</span><h2>A sharper path to permit-ready.</h2></div><p>We organize the early decisions that make or break a property project: feasibility, scope, drawings, agency requirements, energy documentation, and coordination with licensed professionals when required.</p></div>${cards([['ADU plans','Detached, attached, and interior ADU design shaped around your lot, goals, and local review requirements.','adu-design.html'],['Conversions','Garage and existing-space conversions with measured plans, code coordination, and a practical permit path.','garage-conversion.html'],['Additions + remodels','Thoughtful residential changes with clear documentation for pricing, coordination, and review.','additions-remodels.html']])}</div></section><section class="split"><img class="split-media" src="media/adu-concept-1.webp" width="1024" height="1024" loading="lazy" alt="Concept visualization of a compact modern backyard home"><div class="split-copy"><span class="eyebrow">Built around the real process</span><h2>Design is only useful when it moves.</h2><p>A beautiful drawing is not the finish line. Forma builds the project information, consultant inputs, and jurisdiction responses into one coordinated workflow.</p><ul class="proof-list"><li>Site and project discovery</li><li>Concept and space planning</li><li>Permit drawing development</li><li>Title 24 and engineering coordination</li><li>Agency comments and revisions</li></ul><a class="button ghost" href="process.html">See the process</a></div></section><section class="section dark"><div class="container"><div class="section-head"><div><span class="eyebrow">Why Forma</span><h2>Less guesswork. Better decisions.</h2></div><p>We help owners understand the work before construction pricing and help contractors receive clearer information before building begins.</p></div>${cards([['Scope first','We identify the actual project, decision-makers, constraints, and expected deliverables before drawing.'],['One coordinated team','Forma coordinates architecture, structural engineering, energy documentation, and contractor input as the project requires.'],['Straight communication','You get plain-language updates, defined milestones, and visibility into what is needed next.']])}</div></section>${cta('Have a property in mind?')}</main>${footer()}<script src="site.js" defer></script></body></html>`);

page({file:'services.html',active:'services.html',title:'Residential Design & Permit Services in California | Forma',description:'Explore Forma services for custom homes, residential design, ADUs, garage conversions, additions, remodels, permit plans, and commercial improvements.',h1:'Design that moves projects forward.',intro:'From custom homes and residential planning to ADUs and permit coordination, Forma helps owners and contractors make each project clear, reviewable, and ready for the next decision.',body:`<section class="section"><div class="container">${cards([['Custom homes + residential design','Site-responsive concepts, floor plans, exterior design, and coordinated documentation for new homes and residential projects.','custom-home-design.html'],['ADU design','Site-aware layouts and coordinated plan sets for detached, attached, and interior ADUs.','adu-design.html'],['Garage conversions','Plans for turning existing garages into functional living space while addressing safety and code needs.','garage-conversion.html'],['Additions + remodels','Residential layouts, exterior studies, and permit documentation for changing homes.','additions-remodels.html'],['Permit services','Submittal organization, jurisdiction coordination, corrections, and resubmittals.','permit-services.html'],['Commercial plans','Tenant improvements and office buildout documentation for defined, small commercial scopes.','commercial-plans.html']])}</div></section>${cta()}`,schemaExtra:serviceSchema('Residential design and permit coordination','services.html','Custom home, residential, ADU, remodel, addition, and light-commercial design documentation and permit coordination in California.')});

page({file:'adu-design.html',active:'adu-design.html',title:'ADU Design & Permit Plans in California | Forma',description:'Custom ADU design, site planning, permit drawings, Title 24 coordination, and structural engineering coordination for California homeowners.',h1:'ADU plans shaped around your property.',intro:'Detached, attached, interior, and garage-conversion ADUs need more than a floor plan. We coordinate the site, design, documentation, and consultants needed for a complete permit path.',body:`<section class="section"><div class="container"><div class="section-head"><div><span class="eyebrow">ADU scope</span><h2>From backyard idea to coordinated package.</h2></div><p>We begin with your property, your intended use, and the reviewing jurisdiction. Then we build a plan around access, privacy, utilities, existing structures, buildability, and the documents required for review.</p></div>${cards([['Feasibility + site fit','Review of available property information, project goals, likely constraints, and possible directions.'],['Custom design','Floor plans and exterior concepts developed for the site—not a generic one-size-fits-all promise.'],['Permit documentation','Coordinated drawings, schedules, details, and consultant inputs prepared for agency review.']])}<div class="content"><h2>What may be coordinated</h2><ul><li>Existing conditions and site plan</li><li>Floor plans, roof plan, elevations, and building sections</li><li>Door, window, finish, and equipment information as appropriate</li><li>Title 24 energy documentation through a qualified provider</li><li>Structural calculations and details through a licensed engineer</li><li>Licensed architect review or stamp where the project requires it</li><li>Agency comments and drawing revisions within the agreed scope</li></ul><div class="notice">Concept imagery and sample plans on this site are illustrative. Every property and jurisdiction is different; final scope, code requirements, fees, and approvals are determined after project review.</div><h2>Common questions</h2>${faq([['Do you sell permit-ready stock plans?','We show concept layouts for inspiration, but a permit package must be adapted to its property, jurisdiction, utilities, and required consultant work.'],['Can Forma submit the permit?','Permit coordination and submittal support are available as part of an agreed project scope. Owner signatures, fees, and jurisdiction-specific processes still apply.'],['Do you provide engineering and Title 24?','Forma coordinates qualified structural and energy professionals when required. Their services and deliverables are defined in the project proposal.']])}</div></div></section>${cta('Planning an ADU?')}`,schemaExtra:serviceSchema('ADU design and permit plans','adu-design.html','Custom accessory dwelling unit design and permit coordination in California.')});

page({file:'garage-conversion.html',active:'services.html',title:'Garage Conversion Plans in California | Forma',description:'Garage conversion design and permit plans for California homeowners, including existing conditions, code coordination, and consultant management.',h1:'Turn existing space into useful space.',intro:'A garage conversion can create a home office, living area, or ADU—but the design must account for the existing structure, life safety, energy requirements, and local review.',body:`<section class="section"><div class="container">${cards([['Document existing conditions','We establish the current layout and visible conditions that affect the proposed conversion.'],['Design the new use','We plan circulation, light, ventilation, privacy, storage, utilities, and the relationship to the main home.'],['Coordinate permit needs','We organize the drawings and outside professional inputs required for the agreed permit scope.']])}<div class="content"><h2>Why conversions need careful planning</h2><p class="lead">The walls may already exist, but the space was not necessarily built as habitable area.</p><p>Conversions often require analysis of ceiling height, insulation, egress, fire separation, electrical service, plumbing, heating and cooling, foundations, and parking or zoning rules. Forma identifies the design questions early and coordinates the documentation needed to resolve them.</p><h2>Deliverables are project-specific</h2><p>Your proposal will define measured drawings, design options, permit sheets, consultant coordination, and agency-response support. Construction and trade work are performed by properly licensed contractors under separate agreements.</p></div></div></section>${cta('Explore a garage conversion.')}`,schemaExtra:serviceSchema('Garage conversion design','garage-conversion.html','Garage conversion and permit plan services for California properties.')});

page({file:'additions-remodels.html',active:'services.html',title:'Home Addition & Remodel Plans in California | Forma',description:'Residential design and permit plan services for home additions and remodels across California, with consultant and permit coordination.',h1:'Make the home work better.',intro:'Forma plans additions and remodels around how you live, how the existing building works, and what the reviewing agency needs to see.',body:`<section class="section"><div class="container">${cards([['Programming','Translate priorities, room needs, budget context, and future plans into a clear brief.'],['Design development','Test layouts and exterior relationships before committing to detailed documentation.'],['Permit coordination','Develop the agreed plan set and coordinate the outside technical work required for submittal.']])}<div class="content"><h2>Designed for decisions</h2><p>Good renovation documents help more than the agency reviewer. They give contractors a clearer basis for pricing, reveal coordination questions earlier, and reduce improvisation during construction.</p><h2>Typical project types</h2><ul><li>Bedroom, bathroom, and living-area additions</li><li>Kitchen and whole-home remodels</li><li>Primary-suite reconfiguration</li><li>Exterior changes and covered outdoor areas</li><li>Existing-space conversions and legalization scopes</li></ul></div></div></section>${cta('Plan your next chapter.')}`,schemaExtra:serviceSchema('Home addition and remodel plans','additions-remodels.html','Design and permit documentation for residential additions and remodels in California.')});

page({file:'permit-services.html',active:'services.html',title:'Permit Plan & Coordination Services | Forma California',description:'Permit plan preparation, submittal organization, consultant coordination, and correction response support for California building projects.',h1:'A clearer permit path.',intro:'We organize project documents, outside consultants, submittal requirements, and review comments so the process is easier to understand and act on.',body:`<section class="section"><div class="container"><div class="content"><p class="lead">Permitting is a review process, not a one-click approval. The best way to reduce avoidable delay is to submit a coordinated package and respond clearly when reviewers ask for changes.</p><h2>How Forma supports permitting</h2><ul><li>Jurisdiction and submittal-requirement research</li><li>Drawing and consultant-package coordination</li><li>Digital submission organization when included in scope</li><li>Plan-check comment review and response tracking</li><li>Revisions to Forma drawings within the agreed scope</li><li>Communication checkpoints with the owner and project team</li></ul><h2>What stays transparent</h2><p>Agency fees, review timing, approvals, third-party consultant fees, and construction costs are controlled by others and cannot be guaranteed. Forma defines its services and assumptions in the project proposal so responsibilities are clear.</p>${faq([['Can you guarantee permit approval?','No consultant can responsibly guarantee an agency decision. We can prepare and coordinate the agreed documents, address review comments, and keep responsibilities visible.'],['Are city fees included?','Jurisdiction fees and assessments are typically paid directly by the owner and are separate unless a proposal explicitly says otherwise.'],['How long does review take?','Timing depends on the jurisdiction, project complexity, submission completeness, and review cycles. We provide project-specific expectations after initial discovery.']])}</div></div></section>${cta()}`,schemaExtra:serviceSchema('Permit plan and coordination services','permit-services.html','Permit documentation, submittal coordination, and corrections support in California.')});

page({file:'commercial-plans.html',active:'services.html',title:'Commercial Tenant Improvement Plans | Forma California',description:'Plan, design, documentation, and permit coordination for defined office and light-commercial tenant improvement projects across California.',h1:'Clear plans for defined commercial scopes.',intro:'Forma supports office layouts and light-commercial tenant improvements where organized documentation and consultant coordination can keep the project moving.',body:`<section class="section"><div class="container">${cards([['Scope confirmation','Clarify occupancy, existing conditions, intended use, landlord requirements, and likely consultants.'],['Space planning','Develop a practical layout around operations, circulation, accessibility, and the existing shell.'],['Permit set coordination','Coordinate architectural documentation with engineering or specialty consultants required for the project.']])}<div class="content"><h2>Fit matters</h2><p>Commercial work ranges widely in complexity. Forma evaluates each inquiry before accepting the project and brings in licensed architecture, engineering, accessibility, fire/life-safety, or MEP expertise when required. Services are defined in writing before work begins.</p></div></div></section>${cta('Discuss a commercial project.')}`,schemaExtra:serviceSchema('Commercial tenant improvement plans','commercial-plans.html','Design documentation for office and light-commercial tenant improvements in California.')});

page({file:'process.html',active:'process.html',title:'Our Design & Permit Process | Forma',description:'See Forma’s step-by-step process for feasibility, design, permit drawings, consultant coordination, agency review, and construction handoff.',h1:'A process you can see.',intro:'Every project is different, but the work should never feel mysterious. We use defined milestones, decisions, and deliverables from discovery through permit review.',body:`<section class="section"><div class="container"><div class="process-list"><article class="process-step"><h3>Discover</h3><p>Confirm the property, goals, desired use, decision-makers, known constraints, and the information available.</p></article><article class="process-step"><h3>Define</h3><p>Set the service scope, deliverables, outside consultants, assumptions, schedule framework, and fee structure.</p></article><article class="process-step"><h3>Design</h3><p>Develop the site relationship, layout, form, and key selections through reviewable design checkpoints.</p></article><article class="process-step"><h3>Document</h3><p>Prepare the agreed drawing package and coordinate structural, energy, or other technical inputs.</p></article><article class="process-step"><h3>Submit + respond</h3><p>Organize the submittal and track agency comments, owner decisions, and drawing revisions within scope.</p></article><article class="process-step"><h3>Hand off</h3><p>Issue the approved or final documents and support an organized transition to contractor pricing and construction.</p></article></div><div class="content"><h2>Communication at every milestone</h2><p>Our proposals identify what is included, what is excluded, and what information we need from you. If the project changes, we explain the impact before expanding the work.</p></div></div></section>${cta()}`});

page({file:'packages.html',active:'services.html',title:'Project Service Paths | Forma Design Consultants',description:'Compare Forma service paths for project feasibility, design documentation, and coordinated permit support—customized to your property and goals.',h1:'The right scope for the real project.',intro:'Instead of forcing every property into a fixed package, Forma builds a service proposal around the project type, site, jurisdiction, deliverables, and coordination needs.',body:`<section class="section"><div class="container">${cards([['Feasibility review','A focused first step for owners who need to understand options, constraints, and the likely path before full design.'],['Design documentation','Concept development and agreed drawing deliverables for projects that need a clear design direction.'],['Design + permit coordination','A fuller path including permit-plan development, consultant coordination, and agency-response support.']])}<div class="content"><h2>Why pricing is project-specific</h2><p>Lot conditions, existing documentation, jurisdiction rules, project size, structural scope, consultant needs, and number of review cycles can materially change the work. We review the basic facts before presenting a written scope and fee.</p><h2>Every proposal should tell you</h2><ul><li>What Forma will produce</li><li>How many design or revision rounds are included</li><li>Which outside consultants are expected</li><li>Which agency and third-party fees are separate</li><li>What information the owner must provide</li><li>How additional services are approved</li></ul></div></div></section>${cta('Get a project-specific scope.')}`});

page({file:'team.html',active:'team.html',title:'About Forma Design Consultants | California',description:'Meet the operations and design leadership behind Forma’s practical, coordinated approach to California project planning and permitting.',h1:'A coordinated design team.',intro:'Forma combines project operations and design leadership with a network of licensed architects, engineers, energy consultants, and contractors brought in as the project requires.',body:`<section class="section"><div class="container">${cards([['Cody Lindo','<strong>Operations Manager</strong><br>Operations, marketing, permitting coordination, and client communication. Cody keeps scope, decisions, and next steps visible.'],['Jesús Izazaga','<strong>Principal Designer</strong><br>Jesús leads drafting, spatial design, and drawing development, turning project goals into coordinated documents.'],['Licensed project partners','Forma coordinates licensed architects and engineers for professional services, stamps, calculations, and review where required.']])}<div class="content"><h2>What “consultants” means here</h2><p>Forma Design Consultants is the client-facing brand of Forma Consulting Co. LLC. We do not present every team member as a licensed architect, engineer, or contractor. Regulated professional services and construction are provided by appropriately licensed professionals under the agreements applicable to each project.</p><h2>Our working principles</h2><ul><li>Say what is known—and what still needs verification</li><li>Define scope before starting detailed work</li><li>Design around the property and the people using it</li><li>Coordinate specialists instead of leaving owners to connect the pieces</li><li>Keep drawings, decisions, and communications organized</li></ul></div></div></section>${cta('Meet us through your project.')}`});

const contactForm=`<form id="contact-form"><div class="hp" aria-hidden="true"><label>Leave this field empty<input name="website" tabindex="-1" autocomplete="off"></label></div><div class="field-grid"><div class="field"><label for="name">Full name</label><input id="name" name="user_name" autocomplete="name" required></div><div class="field"><label for="email">Email</label><input id="email" name="user_email" type="email" autocomplete="email" required></div><div class="field"><label for="phone">Phone</label><input id="phone" name="user_phone" type="tel" autocomplete="tel" required></div><div class="field"><label for="city">Project city</label><input id="city" name="user_city" autocomplete="address-level2" required></div><div class="field full"><label for="address">Project address or nearest cross streets</label><input id="address" name="user_address" autocomplete="street-address"></div><div class="field full"><label for="project">Project type</label><select id="project" name="project_type" required><option value="">Select one</option><option>Detached ADU</option><option>Attached or interior ADU</option><option>Garage conversion</option><option>Home addition or remodel</option><option>Commercial tenant improvement</option><option>Feasibility review</option><option>Other</option></select></div><div class="field"><label for="timing">Desired timing</label><select id="timing" name="project_timing"><option>Exploring options</option><option>Ready to begin design</option><option>Need permit help now</option><option>Contractor ready</option></select></div><div class="field"><label for="source">How did you find Forma?</label><select id="source" name="discovery_source"><option>Google search</option><option>Instagram</option><option>Referral</option><option>Contractor</option><option>Other</option></select></div><div class="field full"><label for="message">Goals and known details</label><textarea id="message" name="message" rows="6" placeholder="What do you want to create? Tell us what you know about the property, size, use, and current stage." required></textarea></div></div><label class="consent"><input type="checkbox" name="consent" value="yes" required><span>I agree that Forma may use these details to respond to my inquiry. See the <a href="privacy.html">privacy notice</a>.</span></label><p><button class="button" id="submit-btn" type="submit">Send project inquiry</button></p><div class="form-status" id="form-status" role="status" aria-live="polite"></div></form>`;
page({file:'consultant.html',active:'',title:'Request a Project Consultation | Forma',description:'Tell Forma about your California ADU, garage conversion, addition, remodel, or commercial plan project and request an initial consultation.',h1:'Tell us what you want to create.',intro:'Share the project basics below. We’ll review the information and follow up about fit, missing details, and the most useful next step.',body:`<section class="section"><div class="container form-layout"><div><span class="eyebrow">Project intake</span><h2>Useful details create a useful first conversation.</h2><p>Include the city, property address or nearest cross streets, project type, desired use, rough size, and whether you already have drawings or a contractor.</p><div class="notice">Submitting this form does not create a professional-services agreement or guarantee feasibility, timing, cost, or agency approval.</div></div><div class="form-card">${contactForm}</div></div></section><script src="https://cdn.jsdelivr.net/npm/@emailjs/browser@3/dist/email.min.js"></script><script src="form-handler.js"></script>`});

page({file:'contact.html',active:'',title:'Contact Forma Design Consultants | Start a Project',description:'Start a California design or permit-plan project with Forma, call (209) 449-6705, or email cody@formadco.com to discuss your project.',h1:'Choose the right conversation.',intro:'Property owners can start with a project inquiry. Contractors and industry professionals can introduce their services through the partner form.',body:`<section class="section compact white"><div class="container"><div class="trust-grid"><span>Call <a href="tel:+12094496705">(209) 449-6705</a></span><span>Email <a href="mailto:cody@formadco.com">cody@formadco.com</a></span><span>Central Valley based</span><span>California service area</span></div></div></section><section class="section"><div class="container">${cards([['Property owners','Share your property, goals, timing, and current project stage so we can assess fit.','consultant.html'],['Contractors','Introduce your company, trade, service area, license information, and partnership goals.','partner.html'],['Before you submit','Please do not send sensitive financial, identity, or payment information through our forms.','privacy.html']])}</div></section>${cta('Ready to make it clear?')}`});

const partnerForm=`<form id="contractor-form"><div class="hp" aria-hidden="true"><label>Leave blank<input name="website" tabindex="-1"></label></div><div class="field-grid"><div class="field"><label for="company">Company name</label><input id="company" name="company_name" required></div><div class="field"><label for="person">Contact name</label><input id="person" name="contact_person" autocomplete="name" required></div><div class="field"><label for="pemail">Email</label><input id="pemail" name="user_email" type="email" required></div><div class="field"><label for="pphone">Phone</label><input id="pphone" name="user_phone" type="tel" required></div><div class="field"><label for="trade">Trade / role</label><input id="trade" name="trade" required></div><div class="field"><label for="area">Service area</label><input id="area" name="service_area" required></div><div class="field full"><label for="license">License number, if applicable</label><input id="license" name="license_number"></div><div class="field full"><label for="pmessage">Tell us about your work</label><textarea id="pmessage" name="message" rows="5" required></textarea></div></div><label class="consent"><input type="checkbox" required><span>I agree that Forma may use these details to respond to this inquiry.</span></label><p><button class="button" type="submit">Send partnership inquiry</button></p><div class="form-status" role="status" aria-live="polite"></div></form>`;
page({file:'partner.html',title:'Contractor & Consultant Partnerships | Forma',description:'Contractors, engineers, energy consultants, and other California project professionals can introduce their services to Forma.',h1:'Build better project relationships.',intro:'Forma works with qualified professionals who value clear scopes, responsive communication, accurate information, and responsible project delivery.',body:`<section class="section"><div class="container form-layout"><div><span class="eyebrow">Partner network</span><h2>Tell us where you add value.</h2><p>We consider contractors, engineers, Title 24 providers, surveyors, architects, specialty consultants, and real-estate or financing partners relevant to our clients.</p><p>Submitting an inquiry does not create a referral, employment, exclusivity, or subcontractor agreement. Credentials and insurance may be verified before project introductions.</p></div><div class="form-card">${partnerForm}</div></div></section><script src="https://cdn.jsdelivr.net/npm/@emailjs/browser@3/dist/email.min.js"></script><script src="form-handler.js"></script>`});

page({file:'estimate.html',title:'Project Scope Planner | Forma Design Consultants',description:'Use Forma’s project scope planner to organize the information needed for an ADU, conversion, addition, remodel, or permit-plan proposal.',h1:'Plan the scope before guessing the price.',intro:'Construction and design costs depend on the site, jurisdiction, existing conditions, project decisions, and market. Start with a project review instead of an unsupported instant estimate.',body:`<section class="section"><div class="container"><div class="content"><p class="lead">A useful proposal needs useful inputs.</p><h2>Gather these details</h2><ul><li>Property address and reviewing jurisdiction</li><li>Project type and desired use</li><li>Approximate area and bedroom or room goals</li><li>Existing surveys, plans, reports, or prior permits</li><li>Known utilities, easements, access, or structural concerns</li><li>Desired timing and whether a contractor is involved</li></ul><h2>What happens next</h2><p>Forma reviews the information, identifies important unknowns, and recommends a feasibility review or project-specific service proposal. We do not promise construction costs, property value increases, agency timelines, or approval outcomes without the necessary investigation.</p><a class="button" href="consultant.html">Start the project intake</a></div></div></section>`});

page({file:'floorplans.html',title:'ADU Concept Floor Plans | Forma',description:'Explore sample ADU layout concepts from Forma, then request a site-specific design and permit-plan scope for your California property.',h1:'Concept plans for better conversations.',intro:'These layouts are visual starting points—not permit-ready products. Forma adapts room relationships, size, structure, utilities, and documentation to the property and jurisdiction.',body:`<section class="section white"><div class="container"><div class="media-grid"><figure class="media-card"><img src="media/plan-concept-1.webp" loading="lazy" alt="Sample compact dwelling layout and elevation concept"><figcaption><h3>Compact living concept</h3><p>Sample layout study. Dimensions, labels, code compliance, engineering, and permit suitability require project-specific verification.</p></figcaption></figure><figure class="media-card"><img src="media/plan-concept-2.webp" loading="lazy" alt="Sample accessory dwelling unit floor plan concept"><figcaption><h3>Flexible ADU concept</h3><p>An example of spatial organization only. Not construction documents and not offered as a pre-approved plan.</p></figcaption></figure><figure class="media-card"><img src="media/plan-concept-3.webp" loading="lazy" alt="Sample small residence floor plan concept"><figcaption><h3>Efficient footprint concept</h3><p>A conversation starter for scale and room relationships. Site adaptation and full documentation are required.</p></figcaption></figure><figure class="media-card"><img src="media/adu-concept-2.webp" loading="lazy" alt="Architectural concept visualization of a modern accessory dwelling unit"><figcaption><h3>Exterior direction</h3><p>Concept visualization. Final materials, dimensions, systems, and approvals are established through design and documentation.</p></figcaption></figure></div><div class="content"><h2>Why “site-specific” matters</h2><p>Two similar lots can have different utilities, easements, fire access, soils, zoning overlays, existing structures, and agency requirements. A responsible permit package connects the design to those real conditions.</p></div></div></section>${cta('Adapt a concept to your property.')}`});

page({file:'gallery.html',title:'Forma Design Concepts | ADUs & Residential Projects',description:'View Forma concept visualizations and sample design studies for ADUs and residential projects, clearly labeled by project stage.',h1:'Ideas made visible.',intro:'A selection of Forma design concepts and studies. Images are labeled as concepts unless confirmed as completed built work.',body:`<section class="section white"><div class="container"><div class="media-grid">${[['media/adu-concept-1.webp','Compact backyard concept'],['media/adu-concept-2.webp','Modern ADU concept'],['media/adu-concept-3.webp','Residential massing concept'],['media/adu-hero.webp','Courtyard living concept']].map(([src,title])=>`<figure class="media-card"><img src="${src}" loading="lazy" alt="${title} visualization"><figcaption><h3>${title}</h3><p>Design visualization. Not a representation of completed construction unless expressly identified.</p></figcaption></figure>`).join('')}</div></div></section>${cta('Create a project for your property.')}`});

page({file:'custom-home-design.html',active:'services.html',title:'Custom Home Design & Residential Plans | Forma California',description:'Custom home design, residential floor plans, exterior concepts, permit documentation, and consultant coordination for California properties.',h1:'Custom homes designed around real life.',intro:'Forma develops residential designs around the property, the people who will live there, and the decisions required to move from early ideas into coordinated plans.',body:`<section class="section"><div class="container"><div class="section-head"><div><span class="eyebrow">Residential design</span><h2>Not a stock plan with your name added.</h2></div><p>A custom home should respond to how you live, how the property works, the architectural direction you want, and the realities of budget, structure, energy, and permitting.</p></div>${cards([['Discovery + programming','Define room needs, lifestyle priorities, desired character, future flexibility, site opportunities, and the decisions that matter most.'],['Floor plans + exterior design','Develop the circulation, room relationships, massing, elevations, and architectural direction through clear review milestones.'],['Coordinated permit documents','Prepare the agreed residential drawing set and coordinate licensed architecture, structural engineering, energy, and other consultants as required.']])}<div class="content"><h2>Residential projects Forma can support</h2><ul><li>Custom single-family homes</li><li>New residential construction</li><li>Replacement homes and post-loss rebuilding</li><li>Residential floor-plan development</li><li>Exterior and architectural concept design</li><li>Major additions and whole-home transformations</li><li>Small multifamily feasibility and concept planning</li></ul><h2>A coordinated path forward</h2><p>Forma can support design only or a broader design-and-permit scope. Each proposal identifies the project deliverables, review milestones, anticipated licensed consultants, owner responsibilities, and jurisdiction-related work. Construction is performed by properly licensed contractors under separate agreements.</p>${faq([['Does Forma design completely custom floor plans?','Yes. We can develop the layout around your property, program, priorities, and architectural direction rather than forcing the project into a predetermined plan.'],['Can you help with a new home from the beginning?','Yes. Early work can include programming, site-fit thinking, concept development, residential plans, and coordination of the permit-document team.'],['Do you provide construction too?','Forma focuses on design, documentation, permitting, and project coordination. Construction is contracted separately with properly licensed builders.']])}</div></div></section>${cta('Planning a custom home?')}`,schemaExtra:serviceSchema('Custom home and residential design','custom-home-design.html','Custom home design, residential plans, and permit-document coordination for California properties.')});

const cities=[
  ['Modesto','Stanislaus County','adu-plans-modesto.html','City of Modesto','https://permits.modestogov.com/2845/Accessory-Dwelling-Units','Modesto publishes an ADU resource page and directs applicants to its permit process, including site and building-plan documentation.'],
  ['Ceres','Stanislaus County','adu-plans-ceres.html','City of Ceres','https://www.ci.ceres.ca.us/','Ceres properties are reviewed through local planning and building requirements along with applicable California ADU law.'],
  ['Turlock','Stanislaus County','adu-plans-turlock.html','City of Turlock','https://www.cityofturlock.org/buildinginturlock/buildingsafety/postentitlementpermits/','Turlock provides electronic submittal guidance and identifies permit-package screening and plan review as part of the process.'],
  ['Manteca','San Joaquin County','adu-plans-manteca.html','City of Manteca','https://www.manteca.gov/departments/development-services/building-safety/documents','Manteca Development Services publishes building-safety documents, applications, processing resources, and ADU information.'],
  ['Merced','Merced County','adu-plans-merced.html','City of Merced','https://www.cityofmerced.org/departments/development-services/building-division','Merced projects move through the city’s planning and building review process, with project-specific documentation requirements.'],
  ['Patterson','Stanislaus County','adu-plans-patterson.html','City of Patterson','https://www.ci.patterson.ca.us/','Patterson ADU projects require coordination with the local planning and building authority and applicable state standards.'],
  ['Fresno','Fresno County','adu-plans-fresno.html','City of Fresno','https://www.fresno.gov/planning/','Fresno projects require property-specific planning and building review, with coordinated architectural and technical documentation.'],
  ['Stockton','San Joaquin County','adu-plans-stockton.html','City of Stockton','https://www.stocktonca.gov/government/departments/communityDevelop/cdBuild.html','Stockton building review requires a coordinated project package appropriate to the property, scope, and local process.'],
  ['Bay Area','Nine-county Bay Area','adu-plans-bay-area.html','applicable Bay Area city or county','https://abag.ca.gov/technical-assistance/accessory-dwelling-unit-adu-handbook','The Bay Area includes Alameda, Contra Costa, Marin, Napa, San Francisco, San Mateo, Santa Clara, Solano, and Sonoma counties, with many independent local reviewing agencies. Regional resources are a useful starting point, but the property’s city or county controls its planning and building review.'],
  ['San Diego','San Diego County','adu-plans-san-diego.html','City of San Diego','https://www.sandiego.gov/planning/work/housing/toolkit/accessory-dwelling-units','The City of San Diego publishes an ADU toolkit and development guidance. Properties in another incorporated city or an unincorporated part of San Diego County may be reviewed by a different agency.'],
  ['Bakersfield','Kern County','adu-plans-bakersfield.html','City of Bakersfield','https://www.bakersfieldcity.us/1077/Accessory-Dwelling-Units-ADUs-in-Bakersf','Bakersfield publishes a dedicated ADU resource through its Development Services Planning Division. Properties outside city limits may instead fall under Kern County review.'],
  ['Los Angeles','Los Angeles County','adu-plans-los-angeles.html','Los Angeles Department of Building and Safety','https://dbs.lacity.gov/adu','The City of Los Angeles publishes ADU development standards and related resources. Properties elsewhere in Los Angeles County may be reviewed by another incorporated city or by the county.']
];
page({file:'locations.html',active:'locations.html',title:'California Service Areas | Forma Design Consultants',description:'Forma provides ADU design, permit-plan, conversion, addition, and remodel services across the Central Valley, Bay Area, Los Angeles, San Diego, and California.',h1:'Central Valley rooted. California focused.',intro:'Forma is based in the Modesto area and supports residential and defined commercial projects across the Central Valley, Bay Area, Bakersfield, Los Angeles, San Diego, and elsewhere in California, subject to scope and project fit.',body:`<section class="section"><div class="container"><div class="section-head"><div><span class="eyebrow">Local service</span><h2>Start with the reviewing jurisdiction.</h2></div><p>City and county processes vary. We research the actual authority for the property and coordinate the project documents around its current submittal requirements.</p></div><div class="location-grid">${cities.map(([city,county,file])=>`<a class="location-card" href="${file}"><h3>${city}</h3><span>${county} →</span></a>`).join('')}</div><div class="content"><h2>Outside these cities?</h2><p>We consider projects elsewhere in California. Tell us the property location and project type so we can confirm fit, availability, and the likely consultant team.</p></div></div></section>${cta()}`});
cities.forEach(([city,county,file,jurisdiction,url,note])=>page({file,active:'locations.html',title:`ADU Design & Permit Plans in ${city}, CA | Forma`,description:`ADU design, site planning, permit drawings, and consultant coordination for ${city}, California homeowners. Start with a property-specific review.`,h1:`ADU plans for ${city} properties.`,kicker:`${city}, California`,intro:`Forma helps ${city} property owners turn an ADU idea into a coordinated design and permit-plan scope shaped around the site, intended use, and local review process.`,body:`<section class="section"><div class="container">${cards([['Property review',`Start with the ${city} address, available records, existing structures, access, utilities, and your goals.`],['Site-specific design','Develop a layout and exterior direction around privacy, usability, lot fit, and buildability.'],['Permit coordination',`Coordinate drawings, energy documentation, engineering, and responses needed for the agreed ${jurisdiction} process.`]])}<div class="content"><h2>Planning an ADU in ${city}</h2><p>${note} Forma verifies the applicable jurisdiction and current project requirements during scope development rather than relying on a generic checklist.</p><p><a href="${url}" rel="noopener" target="_blank">Visit the ${jurisdiction} resource →</a></p><h2>What to send first</h2><ul><li>The property address</li><li>Your preferred ADU type and intended use</li><li>Any existing plans, surveys, permits, or utility information</li><li>Desired room count and approximate size</li><li>Known access, easement, or existing-building issues</li></ul><div class="notice">Local and state requirements change. This page is general information, not legal or code advice. Current requirements, fees, and feasibility must be verified for the specific property.</div></div></div></section>${cta(`Start an ADU in ${city}.`)}`,schemaExtra:serviceSchema(`ADU design in ${city}, California`,file,`ADU design and permit coordination for properties in ${city}, ${county}.`)}));

page({file:'privacy.html',title:'Privacy Notice | Forma Design Consultants',description:'Learn how Forma Design Consultants handles information submitted through its website and project inquiry forms.',h1:'Privacy notice.',kicker:'Last updated August 16, 2026',intro:'This notice explains the information submitted through this website and how it is used to respond to inquiries.',body:`<section class="section"><div class="container content"><h2>Information you provide</h2><p>Forms may collect your name, email, phone number, project city or address, company details, project description, and other information you choose to provide.</p><h2>How information is used</h2><p>Forma uses submitted information to evaluate and respond to inquiries, communicate about potential or active projects, improve lead handling, prevent spam, and maintain business records. Do not submit payment-card data, government identification numbers, financial-account details, passwords, or other highly sensitive information.</p><h2>Service providers</h2><p>Website forms use EmailJS to transmit inquiries. Hosting, analytics, and other service providers may process basic device, browser, referral, and usage data if those services are enabled. Their handling is governed by their respective terms and privacy practices.</p><h2>Retention and choices</h2><p>Information may be retained as reasonably needed for inquiry follow-up, legal obligations, and business records. You may request access, correction, or deletion through the project inquiry form. Identity or authority may need to be verified before a request is completed.</p><h2>California notice</h2><p>Forma does not sell personal information through this website. Privacy rights depend on applicable law and circumstances. This notice may be updated as the site and its services change.</p></div></section>`});
page({file:'terms.html',title:'Website Terms | Forma Design Consultants',description:'Terms governing use of the Forma Design Consultants website, concept plans, project information, and inquiry forms.',h1:'Website terms.',kicker:'Last updated August 16, 2026',intro:'These terms apply to general use of this website. A signed project agreement—not the website—defines professional services.',body:`<section class="section"><div class="container content"><h2>General information only</h2><p>Website content is provided for general informational and marketing purposes. It is not architectural, engineering, legal, tax, real-estate, code, construction, or financial advice.</p><h2>No guarantee</h2><p>Forma does not guarantee project feasibility, agency approval, review timing, construction cost, property value, financing, contractor performance, or a particular outcome. Requirements and conditions vary by property and can change.</p><h2>Concepts and intellectual property</h2><p>Images, concepts, layouts, copy, and graphics are protected content. Concept plans and visualizations are not construction documents and may not be relied upon for permitting or building.</p><h2>Professional roles</h2><p>Forma Consulting Co. LLC coordinates design and project services. Licensed architecture, engineering, contracting, and other regulated work is provided by appropriately licensed professionals under applicable agreements when required.</p><h2>Project relationships</h2><p>Submitting a form does not create a client, professional, contractor, referral, partnership, or fiduciary relationship. Services begin only under an accepted written agreement.</p></div></section>`});

page({file:'404.html',title:'Page Not Found | Forma Design Consultants',description:'The requested Forma Design Consultants page could not be found.',h1:'That page moved.',kicker:'404',intro:'The address may be outdated, but your project can still move forward.',body:`<section class="section"><div class="container cta-panel"><div><h2>Find your next step.</h2><p>Explore our design services or tell us about the property you are considering.</p></div><div class="button-row"><a class="button" href="index.html">Go home</a><a class="button ghost" href="consultant.html">Start a project</a></div></div></section>`});

